# A work's date, pages (frbr:embodiment -> fabio:Manifestation) and publisher (a pro:publisher role)
PREFIX frbr: <http://purl.org/vocab/frbr/core#>
PREFIX fabio: <http://purl.org/spar/fabio/>
PREFIX prism: <http://prismstandard.org/namespaces/basic/2.0/>
PREFIX pro: <http://purl.org/spar/pro/>
PREFIX oco: <https://w3id.org/oc/ontology/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT ?title ?date ?first ?last ?publisher WHERE {
  <https://w3id.org/oc/meta/br/06270426> dcterms:title ?title .
  OPTIONAL { <https://w3id.org/oc/meta/br/06270426> prism:publicationDate ?date }
  OPTIONAL { <https://w3id.org/oc/meta/br/06270426> frbr:embodiment ?e . ?e prism:startingPage ?first ; prism:endingPage ?last }
  OPTIONAL { <https://w3id.org/oc/meta/br/06270426> pro:isDocumentContextFor ?r . ?r pro:withRole pro:publisher ; pro:isHeldBy ?p .
             ?p foaf:name ?publisher }
}

# A work's provenance: every snapshot of its record (created, modified, merged, deleted), when, from which source and by whom, in the named graph <work/prov/>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT ?snapshot ?generated ?invalidated ?description ?source ?agent WHERE {
  GRAPH <https://w3id.org/oc/meta/br/06270426/prov/> {
    ?snapshot prov:specializationOf <https://w3id.org/oc/meta/br/06270426> ; prov:generatedAtTime ?generated .
    OPTIONAL { ?snapshot dcterms:description ?description }
    OPTIONAL { ?snapshot prov:invalidatedAtTime ?invalidated }
    OPTIONAL { ?snapshot prov:hadPrimarySource ?source }
    OPTIONAL { ?snapshot prov:wasAttributedTo ?agent }
  }
} ORDER BY ?generated

# What changed in a work's record: the SPARQL update OpenCitations applied at each modification (oco:hasUpdateQuery), with the snapshot it derives from
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX pro: <http://purl.org/spar/pro/>
PREFIX oco: <https://w3id.org/oc/ontology/>
SELECT ?snapshot ?generated ?previous ?update WHERE {
  GRAPH <https://w3id.org/oc/meta/br/06270426/prov/> {
    ?snapshot prov:specializationOf <https://w3id.org/oc/meta/br/06270426> ; prov:generatedAtTime ?generated ;
              oco:hasUpdateQuery ?update .
    OPTIONAL { ?snapshot prov:wasDerivedFrom ?previous }
  }
} ORDER BY ?generated
